"""Job-mode pydantic-ai agent that implements an approved :class:`AgentBuildPlan`.

Runs once, headless, inside ``run_plan_to_bot_job``: no streaming, no chat
history persistence, no git commits (the job commits once validation passes).
The agent gets the same native file tools and Mantle system prompt as the
interactive Copilot v2 runtime, plus one local tool to validate the project it
is editing. Writing skills is its whole task, so the ``building-skills`` Copilot
skill is part of its instructions from the start rather than loaded on demand.
"""

from __future__ import annotations

import asyncio
import uuid

import structlog

try:
    from pydantic_ai import Agent, RunContext
    from pydantic_ai.settings import ModelSettings
    from pydantic_ai.usage import UsageLimits
except ImportError as exc:
    raise ImportError(
        "pydantic-ai-slim is required for Copilot v2. "
        "Install with: pip install rasa-pro[copilot-v2]"
    ) from exc

from rasa.builder.agent_plan.models import AgentBuildPlan
from rasa.builder.copilot.pydantic_ai.config import PydanticAIConfig
from rasa.builder.copilot.pydantic_ai.file_tools import register_file_tools
from rasa.builder.copilot.pydantic_ai.prompt_loader import MANTLE_SYSTEM_PROMPT
from rasa.builder.copilot.pydantic_ai.run_context import CopilotRunContext
from rasa.builder.copilot.pydantic_ai.skills import (
    register_skill_tools,
    skill_capabilities,
)
from rasa.builder.copilot.pydantic_ai.types import RunRequest
from rasa.builder.copilot.skill_catalog import CopilotSkill, get_skill_catalog
from rasa.builder.exceptions import ValidationError
from rasa.builder.job_helpers import validate_project_for_generator
from rasa.builder.project_generator.project_generator import ProjectGenerator

structlogger = structlog.get_logger()

BUILDER_TASK_INSTRUCTIONS = """
# Task
You are building a NEW Mantle agent from an approved plan (provided in the user message as JSON). The project was just scaffolded from the template. Implement the plan:
- Write skills/<id>/skill.md for each planned skill, following the building-skills instructions: YAML frontmatter (the plan's id as `name`, and its description), markdown body implementing the outline.
- Update agent.yml with the plan's name and persona summary.
- Declare memory entries a skill writes (follow the template's existing conventions).
- Then call validate_project and fix every finding. Stop when validation passes.
Do not train (the job only validates after you finish). Do not invent skills beyond the plan. Remove template example skills that the plan does not include.
"""  # noqa: E501

BUILDER_SYSTEM_PROMPT = MANTLE_SYSTEM_PROMPT + "\n" + BUILDER_TASK_INSTRUCTIONS

VALIDATE_PROJECT_TOOL_NAME = "validate_project"

# Copilot skills the builder always has. Their ``tools:`` must be tools this
# agent registers.
BUILDER_SKILL_NAMES = ("building-skills",)


def _builder_skills() -> tuple[CopilotSkill, ...]:
    """Return the packaged Copilot skills the builder gets.

    A skill missing from the catalog (for example one that failed to load) is
    logged and left out, so the build still runs without it.
    """
    catalog = get_skill_catalog()
    skills = []
    for name in BUILDER_SKILL_NAMES:
        skill = catalog.get(name)
        if skill is None:
            structlogger.warning("agent_plan.builder.skill_missing", skill_name=name)
            continue
        skills.append(skill)
    return tuple(skills)


def _build_agent(
    project_generator: ProjectGenerator, skills: tuple[CopilotSkill, ...] = ()
) -> Agent[CopilotRunContext, str]:
    """Construct the plan-builder agent.

    Its ``validate_project`` tool is closed over *project_generator*. *skills*
    are added to its instructions up front, and their reference files are
    readable with ``load_skill_reference``.
    """
    config = PydanticAIConfig()
    agent: Agent[CopilotRunContext, str] = Agent(
        config.model_name,
        name="copilot_v2_plan_builder",
        deps_type=CopilotRunContext,
        output_type=str,
        system_prompt=BUILDER_SYSTEM_PROMPT,
        model_settings=ModelSettings(timeout=config.stream_event_timeout),
        capabilities=skill_capabilities(skills, defer_loading=False),
    )
    register_file_tools(agent)
    register_skill_tools(agent)

    @agent.tool(
        name=VALIDATE_PROJECT_TOOL_NAME,
        description="Validate the Mantle project and return every finding.",
    )
    async def validate_project(_ctx: RunContext[CopilotRunContext]) -> str:
        """Validate the project being built and return findings as text.

        Never raises: a ``ValidationError`` is caught and its message returned
        as the tool result so the model can act on it, mirroring how every
        other Copilot v2 tool reports failures inline rather than aborting
        the run.
        """
        try:
            await asyncio.to_thread(validate_project_for_generator, project_generator)
        except ValidationError as exc:
            return exc.get_error_message_with_logs()
        return "Validation passed with no findings."

    return agent


async def build_from_plan(
    plan: AgentBuildPlan, project_generator: ProjectGenerator
) -> None:
    """Run the builder agent once against *project_generator*, implementing *plan*.

    Args:
        plan: The approved build plan to implement.
        project_generator: The project generator whose folder was just
            scaffolded from the Mantle template; the agent reads and writes
            files under ``project_generator.project_folder``.
    """
    # Off the event loop: the first call reads the packaged skills from disk.
    skills = await asyncio.to_thread(_builder_skills)
    agent = _build_agent(project_generator, skills)
    deps = CopilotRunContext(
        request=RunRequest(
            thread_id="agent-plan-build",
            run_id=uuid.uuid4().hex,
            messages=(),
        ),
        project_path=str(project_generator.project_folder),
        skills=skills,
    )
    await agent.run(
        plan.model_dump_json(),
        deps=deps,
        usage_limits=UsageLimits(request_limit=30),
    )
